\begin{Theorem}\label{lem:proto1}
For a polyhedral function $g:\R^m\to \oR$  and $(\oz, \olm)\in \gph \partial g$, the following properties hold.
\begin{itemize}[noitemsep,topsep=2pt]
\item [ \rm {(a)}]  The graphical derivative of  $  \sub g$  at $\oz$ for $\olm$ can be obtained by  
\begin{equation}\label{proto4}
\gph D(\sub  g)(\oz,\olm) = T_{\gph\partial g}(\oz, \olm)= \gph N_\Kg.
\end{equation}

\item [ \rm {(b)}]  The strict graphical derivative of  $  \sub g$  at $\oz$ for $\olm$ can be obtained by{\footnote{This formula was brought to our attention by a reviewer.}}  
\begin{equation}\label{proto4n}
\gph D_*(\sub  g)(\oz,\olm) = \gph N_{\Kg}-\gph N_{\Kg}.
\end{equation}

\item [ \rm {(c)}]   The condition   $\olm \in \ri\partial g (\oz)$ amounts to the existence of  a neighborhood $O$ of $(\oz,\olm)$ such that for any $(z,\lm)\in O\cap \gph \sub g$, $\sub g$ is strictly proto-differentiable at $z$ for $\lm$
and its proto-derivative and strict proto-derivative  coincide, namely 
\begin{equation}\label{gdpd}
D_*(\sub  g)(z,\lm)=D(\sub  g)(z,\lm).
\end{equation}
\end{itemize}
\end{Theorem}

