\begin{Lemma}\label{lem:indset} Assume that $g:\R^m\to \oR$ is a polyhedral function and that  $(\oz,\olm)\in\gph\sub g$. Then there exists $r>0$ such that for any decomposition of $\olm$ as 
\eqref{decomp} and any $(z, \lm) \in \big(\gph \partial g\big)\cap \B_r(\oz, \olm)$, we have
\begin{equation}\label{indset7}
 J_+(\oz, \osigma) \subset J(z)\; \; \textrm{ and }\; \; I_+(\oz, \otau) \subset I(z). 
\end{equation}
\end{Lemma}

\begin{proof}
Suppose by contradiction that for each $k\in \N$, there are a decomposition of $\olm  $ as
\begin{equation}\label{indset1}
\olm =  \sum_{j\in J(\oz)}\osigma_j^ka^j+ \sum_{i\in I(\oz)}\otau_i^kb^i\; \; \text{ with }\; \;  \osigma_j^k,\otau_i^k\ge 0\; \text{ and }\; \sum_{j\in J(\oz)}\osigma_j^k=1,
\end{equation}
and $(\zk,\lmk)\in\gph\sub g$ such that $(\zk,\lmk)\to(\oz,\olm)$ as $k\to\infty$ with $J_+^k\not\subset J(\zk)$ or $I_+^k\not\subset I(\zk)$, where $J_+^k:= J_+(\oz,\osigma^k)$ 
and $I_+^k:=I_+(\oz,\otau^k)$ are defined via   \eqref{indset}. Since $\zk \to \oz$ as $k\to\infty$, the inclusions  $J(\zk)\subset J(\oz)$
 and $I(\zk)\subset I(\oz)$ hold for all $k$ sufficiently large. Passing to a subsequence if necessary, we can assume that there exist subsets $\bar J\subset J(\oz)$ and $\bar I \subset I(\oz)$ such that
\begin{equation*}
J(\zk)=\bar J \quad \text{ and }\quad I(\zk)=\bar I \quad\text{ for all }k\in \N,
\end{equation*}
which, together with \eqref{subg}, lead us to 
\begin{equation*}
\partial g(\zk) = \co\big\{a^j|\, j\in \bar J\big\}+\cone\big\{b^i|\, i\in \bar I\big\}=:\Omega\quad\textrm{ for all } k\in \N.
\end{equation*}
Since $\lmk \in \partial g(\zk) = \Omega$ and $\lmk\to \olm$ as $k\to\infty$, we arrive at  $\olm\in\Omega =\partial g(\zk)$ for all  $k$ sufficiently large. Fix such a  $k\in \N$ and  deduce from $\olm \in \partial g(\zk)$ that
\begin{equation}\label{indset3}
\la \olm, \oz-\zk\ra \leq g(\oz)-g(\zk).
\end{equation}
By the decomposition in \eqref{indset1}, we obtain  
\begin{align}\label{indset2}
\la \olm, \zk - \oz\ra &= \sum_{j\in J(\oz)} \osigma_j^k\la a^j, \zk-\oz\ra +\sum_{i\in I(\oz)}\otau_i^k\la b^i, \zk - \oz\ra\nonumber\\
&= \sum_{j\in J(\oz)} \osigma_j^k\big(\la a^j, \zk\ra - \alpha_j - g(\oz)\big) +\sum_{i\in  I(\oz)}\otau_i^k \big(\la b^i, \zk\ra - \beta_i\big),\nonumber\\
&\leq \sum_{j\in J(\oz)} \osigma_j^k\big(g(\zk) - g(\oz)\big),
\end{align}
where  the second equality results from  \eqref{indset4} and the last inequality comes from  the fact that $\zk\in \dom g$, combined with  \eqref{dom}--\eqref{polyfunc}. If $J_+^k\not\subset J(\zk)$,  there exists   $\oj\in  J_+^k$ such that $\zk\notin C_\oj$, meaning that 
\begin{equation*}\label{indset5}
\osigma_\oj^k \big(\la a^\oj, \zk\ra - \alpha_\oj - g(\oz)\big) < \osigma_\oj^k \big(g(\zk) - g(\oz)\big).
\end{equation*}
If $I_+^k\not\subset I(\zk)$, we find  $\oi\in I_+^k$ such that $\la b^\oi, \zk\ra <\beta_\oi$, which implies that 
\begin{equation*}\label{indset6}
\otau_\oi^k \big(\la b^\oi, \zk\ra - \beta_\oi\big) < 0,
\end{equation*}
which tells us that  in both cases the last inequality in \eqref{indset2} is strict. Thus, our assumption that either $J_+^k\not\subset J(\zk)$ or $I_+^k\not\subset I(\zk)$, together  with the last condition in \eqref{indset1}, yields
\begin{equation*}
\la \olm, \zk - \oz\ra < \sum_{j\in J(\oz)} \osigma_j^k\big(g(\zk) - g(\oz)\big) = g(\zk) - g(\oz),
\end{equation*}
which contradicts \eqref{indset3} and therefore completes the proof.
\end{proof}

\begin{Proposition}[first-order variational properties] \label{fopg}
Assume that $g:\R^m\to \oR$ is a polyhedral function and $\oz\in \dom g$. Then the following properties  hold.
\begin{itemize}[noitemsep,topsep=2pt]
\item [ \rm {(a)}] The domain of the subderivative function $\d g(\oz)$ can be calculated by 
\begin{equation*}\label{domdg}
\dom \d g(\oz) = T_{\dom g}(\oz) = \bigcup_{j\in J(\oz)} T_{C_j}(\oz).
\end{equation*}
\item [ \rm {(b)}] If $w\in T_{C_j}(\oz)$ for some $j\in J(\oz)$, then we have 
$\d g(\oz) (w) =\la a^j, w\ra$. 
Moreover, there exists $r> 0$ such that  any  $w\in T_{\dom  g}(\oz)\cap \B_r(0)$, the representation 
\begin{equation}\label{approx}
g(\oz + w) = g(\oz) +\d g(\oz)(w)
\end{equation}
holds.
\end{itemize}


\end{Proposition}

\begin{proof} The first equality in (a) was established in \cite[Proposition~10.21]{rw}. The second equality results immediately from the fact that $\dom g=\bigcup_{j\in J} C_j$.
The first claim in  (b) can be found again in \cite[Proposition~10.21]{rw}. To prove  \eqref{approx}, recall that for any $j\in J(\oz)$,    $C_j$ is  a polyhedral convex set. Employing \eqref{tanrep} for these sets, we can find $r>0$ such that
\begin{equation*}
T_{C_j}(\oz)\cap \B_r(0)=(C_j-\oz)\cap \B_r(0)\quad\textrm{ for all }\; j\in J(\oz).
\end{equation*}
Pick any $w \in T_{\dom g}(\oz)\cap \B_r(0)$,  and conclude from  (a) that $w\in T_{C_\oj}(\oz)\cap \B_r(0)$ for some $\oj \in J(\oz)$ and from the first claim in (b) that $\d g(\oz)(w) =\la a^\oj, w\ra$. Thus, we get    $\oz + w \in C_\oj$, which, together with the definition of $C_{j_0}$ and \eqref{indset4}, 
leads us to 
\begin{equation*}
g(\oz+ w) = \la a^\oj, \oz+w\ra-\alpha_\oj = g(\oz) +\la a^\oj, w\ra = g(\oz)+\d g(\oz)(w),
\end{equation*}
and hence completes the proof.
\end{proof}

\begin{Proposition} \label{nonde1} Assume that $g:\R^m\to \oR$ is a polyhedral function and $(\oz, \olm)\in \gph \partial g$. Then the following properties are equivalent:
\begin{itemize}[noitemsep,topsep=2pt]
\item [ \rm {(a)}]  $\olm\in \ri \sub g(\oz)$;
\item [ \rm {(b)}]  the critical cone $K_g(\oz,\olm)$ is a linear subspace.
\end{itemize}
\end{Proposition}

\begin{Proposition} [critical cone of polyhedral functions] \label{prop:cricone} 
Assume that $g:\R^m\to \oR$ is a polyhedral function and $(\oz, \olm)\in \gph \partial g$. If $\olm $ has the decomposition in  \eqref{decomp}, then  $w\in \Kg$ if and only if 
$w$ satisfies the conditions 
\begin{equation*}\label{cricone3}
\begin{cases}
\la a^i-a^j, w\ra = 0,\quad&\textrm{for }\; i,j \in J_+(\oz, \osigma),\\
\la a^i-a^j, w\ra \leq 0 ,&\textrm{for }\; i \in J(\oz)\setminus J_+(\oz, \osigma)\; \textrm{ and }\; j \in J_+(\oz, \osigma),\\
\la b^i, w\ra = 0,&\textrm{for }\; i \in I_+(\oz, \otau),\\
\la b^i, w\ra\leq 0,&\textrm{for }\; i \in I(\oz)\setminus I_+(\oz, \otau).
\end{cases}
\end{equation*}
\end{Proposition}

\begin{Theorem}[reduction lemma]\label{thm:reduction}
Assume that $g:\R^m\to \oR$ is a polyhedral function and $(\oz, \olm)\in \gph \partial g$.  Then there exists $r>0$ such that
\begin{equation}\label{reduction}
\big( (\gph \sub g ) - (\oz, \olm)\big)\cap \B_r(0,0) = \big(\gph N_\Kg\big)\cap \B_r(0,0).
\end{equation}
\end{Theorem}

\begin{proof}
Suppose that the polyhedral function $g$  has the representation   \eqref{polyfunc}. We first show that there is $r>0$ for which
the inclusion `$\supset$' in \eqref{reduction} holds. To do so, using  \eqref{tanrep} for the polyhedral convex set $\partial g(\oz)$, we find $r_0>0$ such that 
\begin{equation}\label{relem1}
T_{\partial g(\oz)}(\olm)\cap \B_{r_0}(0) = \big(\partial g(\oz) -\olm\big)\cap \B_{r_0}(0).
\end{equation}
Pick now a pair $(w, u)$ from the right-hand side of \eqref{reduction} with $r=r_0$ therein, which implies that  the conditions $w\in \Kg\cap\B_{r_0}(0)$, $u \in \Kg^*\cap \B_{r_0}(0)$, and $\la u, w\ra =0$
are satisfied. Moreover, using \eqref{cricone1} for the polyhedral function $g$, we get $\Kg^*= T_{\partial g(\oz)}(\olm)$. Therefore $u$ belongs to the left-hand side of \eqref{relem1}, and thus $\olm+u \in\partial g(\oz)$. We now show that $(\oz +w, \olm +u) \in\gph\partial g$. To this end, take $z\in \R^m$   and observe that 
\begin{equation}\label{relem2}
\la \olm+u, z- (\oz+w)\ra = \la \olm+u, z-\oz\ra -\la\olm, w\ra - \la u, w\ra\leq g(z)-g(\oz) - \d g(\oz)(w),
\end{equation}
where the last inequality is deduced from the facts that $\olm +u \in \partial g(\oz)$, $w\in \Kg$, and $\la u, w\ra =0$. Choosing a smaller radius $r_0$ if necessary, we can assume that  \eqref{approx} is valid on
 $T_{\dom g}(\oz)\cap \B_{r_0}(0)$. It follows from Proposition~\ref{fopg}(a) and $w\in \Kg\cap \B_{r_0}(0)$ that $w\in T_{\dom g}(\oz)\cap \B_{r_0}(0)$, which in turn allows us to conclude via \eqref{approx} that
  $g(\oz)+\d g(\oz)(w) = g(\oz+w)$. Combining this and  \eqref{relem2} leads us to 
\begin{equation*}
\la \olm+u, z- (\oz+w)\ra \leq g(z)-g(\oz+w)
\end{equation*}
for any arbitrary $z\in \R^m$, and thus  to $\olm+u \in \partial g(\oz+w)$. This proves that  $(w, u)$ belongs to the left-hand side of \eqref{reduction} with $r=r_0$.



We now proceed with proving the inclusion `$\subset$' in \eqref{reduction} for some $r>0$. Decompose $\olm$ into $\olm = \olm_1+\olm_2$ with $\olm_1, \olm_2$ taken from  \eqref{decomp}. 
Pick $r_0$ from \eqref{relem1} and choose $r\in (0, r_0]$  such that the inclusions in \eqref{indset7} hold for all $(z, v)\in \big(\gph\partial g\big)\cap\B_{r}(\oz, \olm)$. Pick now a pair $(w, v)$ from the left-hand side of \eqref{reduction}, and conclude that  
 $(w, u) \in \B_{r}(0, 0)$ with $\olm+u \in \partial g(\oz+w)$. We are going to show that  $u\in N_\Kg(w)$, which amounts via \cite[Proposition~2A.3]{DoR14} to the conditions
\begin{equation}\label{relem4}
w\in \Kg, \quad u\in \Kg^*, \quad\textrm{ and }\quad \la u, w\ra =0.
\end{equation}
Taking a smaller radius $r$ if necessary, we can assume that $\partial g(\oz+w)\subset \partial g(\oz)$ (cf. \cite[Proposition~3.3(a)]{MoS16}). Thus, $u \in \big(\partial g(\oz) - \olm\big)\cap \B_{r}(0)$. Since $r\leq r_0$, we deduce from  \eqref{relem1} that 
 $u\in T_{\partial g(\oz)}(\olm)= \Kg^*$, which justifies the second inclusion  in \eqref{relem4}. By shrinking $r$ again if necessary, we can derive  from  $(\oz +w, \olm+u) \in  \big(\gph\partial g\big)\cap\B_{r}(\oz, \olm)$ and \eqref{indset7} that 
\begin{equation*}
J_+(\oz, \osigma) \subset J(\oz+w)\subset J(\oz) \quad\textrm{ and }\quad I_+(\oz, \otau)\subset I(\oz+w)\subset I(\oz).
\end{equation*}
 To prove that $w\in \Kg$, we use  Proposition~\ref{prop:cricone} in which an equivalent description of $\Kg$ was given. We break this task into four cases as follows:
\begin{itemize}[noitemsep,topsep=2pt]
\item [ \rm {(i)}]   $i, j \in J_+(\oz, \osigma)$. In this case, we obtain from  the inclusions above  that $i, j \in  J(\oz+w)\subset J(\oz)$. These inclusions bring us via \eqref{indset4} to  
\begin{equation*}
\la a^i, \oz\ra -\alpha_i = \la a^j, \oz\ra -\alpha_j\quad\textrm{ and }\quad
\la a^i, \oz+w\ra -\alpha_i = \la a^j, \oz+w\ra -\alpha_j.
\end{equation*}
Combining  these confirms that $\la a^i-a^j, w\ra  =0$ for all $i, j \in J_+(\oz, \osigma)$.

\item [ (ii)]  $i\in J(\oz)\setminus J_+(\oz, \osigma)$ and $j\in J_+(\oz, \osigma)$. In this case, we arrive at $i, j\in J(\oz)$ and $j\in J(\oz+v)$, which imply via \eqref{indset4} that  
\begin{equation*}
\la a^i, \oz\ra -\alpha_i = \la a^j, \oz\ra -\alpha_j\quad\textrm{ and }\quad
\la a^i, \oz+w\ra -\alpha_i \leq \la a^j, \oz+w\ra -\alpha_j.
\end{equation*}
Combining  these confirms that $\la a^i-a^j, w\ra  \le 0$ for all $i\in J(\oz)\setminus J_+(\oz, \osigma)$ and $j\in J_+(\oz, \osigma)$.

\item [{(iii)}]  $i\in I_+(\oz, \otau)$. In this case, we have $i\in I(\oz)$ and $i \in I(\oz+w)$, which result in $\la b^i, \oz\ra =\la b^i, \oz+w\ra=\beta_i$. Combining  these confirms that $\la b^i, w\ra=0$ for all $i\in I_+(\oz, \otau)$.

\item[(iv)]  $i\in I(\oz)\setminus I_+(\oz, \otau)$. In this case,  we deduce from $\oz+w\in \dom g$ and $i\in I(\oz)$ that $\la b^i, \oz+w\ra \leq \beta_i=\la b^i, \oz\ra$, which in turn yields  
$\la b^i, w\ra\le 0$ for all $i\in I(\oz)\setminus I_+(\oz, \otau)$.
\end{itemize}
In summary, we showed that $w$ satisfies the equivalent description of $\Kg$ from Proposition~\ref{prop:cricone}, and so $w\in \Kg$. 
It remains to demonstrate that $\la w,u\ra=0$. Recall that $\olm+u\in \partial g(\oz+w)$. Using \eqref{subg}, we can express $\olm+u$ as
\begin{equation*}\label{relem5}
\olm + u = \sum_{j\in J(\oz+w)} \sigma_j a^j+ \sum_{i\in I(\oz+w)} \tau_ib^i\; \; \textrm{ with }\; \; \sigma_j, \tau_i \geq 0\; \textrm{ and }\;  \sum_{j\in J(\oz+w)} \sigma_j =1.
\end{equation*}
This and the decomposition $\olm = \olm_1+\olm_2$ with $\olm_1,\olm_2$ taken from \eqref{decomp} allow us to conclude that  
\begin{align*}
\la u, w\ra &= \la \olm+u, w\ra-\la \olm, w\ra\\
&= \sum_{j\in J(\oz+w)} (\sigma_j-\osigma_j)\la a^j, w\ra+ \sum_{i\in I(\oz+w)} (\tau_i-\otau_i)\la b^i, w\ra\\
&= \sum_{j\in J(\oz+w)} (\sigma_j-\osigma_j)\big[\la a^j, \oz+w\ra-\alpha_j -(\la a^j, \oz\ra-\alpha_j)\big]+ \sum_{i\in I(\oz+w)} (\tau_i-\otau_i)\big[\la b^i, \oz+w\ra - \la b^i, \oz\ra\big]\\
&= \big(g(\oz+w)-g(\oz)\big)\sum_{j\in J(\oz+w)} (\sigma_j-\osigma_j)+ \sum_{i\in I(\oz+w)} (\tau_i-\otau_i)(\beta_i-\beta_i)\\
&=0,
\end{align*}
where  the second equality  results from the inclusions $J_+(\oz, \osigma)\subset J(\oz+w)$ and  $ I_+(\oz, \otau)\subset I(\oz+w)$, 
 where   the fourth equality comes from the  definitions of the active index sets $J(\oz+w)$ and $I(\oz+w)$ as well as the inclusions $J(\oz+w)\subset J(\oz)$ and $I(\oz+w)\subset I(\oz)$, 
 and where  the last equality follows from the assumption on $\sigma_j$ and $\osigma_j$. This proves the inclusion `$\subset$' in \eqref{reduction} for some $r>0$ and thus completes the proof. 
\end{proof}

\begin{Corollary}[polar relation of critical cones] \label{polarity}
Assume that $g:\R^m\to \oR$ is a polyhedral function and $(\oz, \olm)\in \gph \partial g$.  Then $\Kg$ enjoys the duality relationship 
\begin{equation}\label{cricone2}
\Kg =  K_{g^*}(\olm, \oz)^*.
\end{equation}
Consequently, we have 
\begin{equation}\label{ricond}
\olm \in \ri \partial g(\oz) \; \textrm{ if and only if } \; \oz \in \ri \partial g^*(\olm).
\end{equation}
\end{Corollary}

\begin{Proposition} \label{lem:faces}
Assume that $g:\R^m\to \oR$ is a polyhedral function and $(\oz, \olm)\in \gph \partial g$.
Then there exists $r>0$ such that for all $(z, \lm)\in \big(\gph \partial g\big)\cap \B_r(\oz, \olm)$ the corresponding critical cone $\Kgzv$ enjoys the following representation
\begin{equation*}
\Kgzv = F_1 -F_2,
\end{equation*}
for some faces $F_1, F_2$ of $\Kg$ with $F_2\subset F_1$. Conversely, for any pair of faces $F_1, F_2$ of $\Kg$ with $F_2\subset F_1$ and any sufficiently small real number $r>0$, there exists $(z, \lm)\in \big(\gph \partial g\big)\cap \B_r(\oz, \olm)$ with $\Kgzv = F_1-F_2$.
\end{Proposition}

\begin{proof} 
Let $r>0$ be such that   \eqref{reduction} holds. Choosing a smaller radius $r$ if necessary, we can assume 
without loss of generality that the inclusions $\sub g(z)\subset \sub g(\oz)$ and $N_{\partial g(\oz)}(\lm)\subset N_{\partial g(\oz)}(\olm)$ hold for any $(z, \lm) \in \big(\gph \partial g\big)\cap \B_r(\oz, \olm)$, which can be guaranteed by    $g$ being a polyhedral function. 
We first show that for any  $(z, \lm) \in \big(\gph \partial g\big)\cap \B_r(\oz, \olm)$, we have 
\begin{equation}\label{co6}
\Kgzv = \Kg\cap [\lm-\olm]^\perp +[z-\oz ].
\end{equation}
To this end, pick $(z, \lm) \in \big(\gph \partial g\big)\cap \B_r(\oz, \olm)$ and observe that the inclusion 
\begin{equation}\label{in1}
N_{\partial g(z)}(\lm) \subset N_{\partial g(z)}(\olm)
\end{equation}
holds. To justify it, it is not hard to see $\sub g(z)=\sub g(\oz)\cap D$ with $D:=\{v\in \R^m|\, \la v,z-\oz\ra=g(z)-g(\oz)\}$. 
It follows from $\lm\in \sub g(z)\subset D$ and $\lm-\olm\in N_\Kg(z-\oz)$ that $\olm \in D$. This, together with the definition of $D$, leads us to $N_D(\lm)=N_D(\olm)=[z-\oz]$.
Since both $\sub g(\oz)$ and $D$ are 
polyhedral, we conclude from the intersection rule for normal cones, holding without any constraint qualification for polyhedral convex sets, that 
\begin{eqnarray*}
N_{\partial g(z)}(\lm)&=& N_{\sub g(\oz)\cap D}(\lm)= N_{\partial g(\oz)}(\lm)+N_D(\lm)\\
&\subset& N_{\partial g(\oz)}(\olm) +N_D(\olm) =N_{\sub g(\oz)\cap D}(\olm)=N_{\partial g(z)}(\olm),
\end{eqnarray*}
proving our claimed inclusion.  Since $g^*$ is a polyhedral function as well,  using Lemma~\ref{lem:indset} for $g^*$ at $(\olm,\oz)\in \gph \sub g^*$ and shrinking $r$, if necessary, ensure that $\oz\in \sub g^*(\lm)$.
Moreover, it results from \eqref{in1} that $N_{\partial g^*(\lm)}(z) \subset N_{\partial g^*(\lm)}(\oz)$, which  in combination with \eqref{cricone1}  
leads us to 
\begin{equation*}\label{co5}
K_{g^*}(\lm, z)=N_{\partial g^*(\lm)}(z) = N_{\partial g^*(\lm)}(\oz)\cap [z-\oz]^\perp =K_{g^*}(\lm, \oz)\cap [z-\oz]^\perp.
\end{equation*}
Using this and  \eqref{cricone2} brings us to 
\begin{equation}\label{co8}
\Kgzv =K_{g^*}(\lm, z)^*= \big(K_{g^*}(\lm, \oz)\cap [z-\oz]^\perp\big)^*=K_g(\oz, \lm) +[z-\oz ].
\end{equation}
Similarly, by  \eqref{cricone1}   and the definition of the normal cone to the polyhedral convex set $\sub g(\oz)$, we obtain 
\begin{equation*}\label{co7}
K_g(\oz, \lm) = N_{\partial g(\oz)}(\lm) =N_{\partial g(\oz)}(\olm)\cap [\lm-\olm]^\perp=  \Kg\cap [\lm-\olm]^\perp,
\end{equation*}
which, together with \eqref{co8}, proves \eqref{co6}.    

After these preparations, we are in a position to justify the claimed descriptions of critical cones of $g$. Pick $(z, \lm) \in \big(\gph \partial g\big)\cap \B_r(\oz, \olm)$ and
set $F_1:= \Kg\cap [\lm-\olm]^\perp$, which is clearly a face of $\Kg$. Because $\lm-\olm\in N_\Kg(z-\oz)$, resulting from \eqref{reduction}, we conclude that $z-\oz\in F_1$. 
Since the relative interiors of  nonempty  faces of $F_1$ form a partition of this set (cf. \cite[Theorem~18.2]{Roc70}), we find a face of $F_1$, denoted by $F_2$, that $z-\oz\in \ri F_2$.
This tells us that  $F_2\subset F_1$. Moreover,   $F_2$ is a  face  of $\Kg$ as well.
By \eqref{co6}, the inclusion $\Kgzv \subset F_1 - F_2$ clearly holds. To get the opposite inclusion, pick $x_i\in F_i$ for $i=1,2$. It follows from $z-\oz\in \ri F_2$ and \cite[Theorem~6.4]{Roc70} that there is $t>0$ such that $(1+t)(z-\oz)-tx_2\in F_2\subset F_1$,
which yields 
\begin{equation}\label{in2}
t(x_1-x_2)= tx_1+(1+t)(z-\oz)-tx_2- (1+t)(z-\oz)\in F_1+[z-\oz],
\end{equation}
which confirms via \eqref{co6} that  the inclusion $F_1-F_2\subset \Kgzv$ holds. This shows that  $ \Kgzv=F_1-F_2$.



Assume now that $F_1$ and $F_2$ are faces of $\Kg$ with $F_2\subset F_1$. 
Pick $r>0$ from Theorem \ref{thm:reduction} and choose $u\in \Kg^*$ with $\|u\|<r/2$ such that $F_1 = \Kg\cap [u]^\perp$. Since $u\in \Kg^*=N_\Kg(0)$, it follows from Theorem \ref{thm:reduction} that $\olm+u \in \partial g(\oz)$.
Pick now $w\in \ri F_2$ with $\|w\|<r/2$ and  observe from $w\in F_1$ that $(w, u) \in \gph N_\Kg$.  By Theorem \ref{thm:reduction}, we arrive at $(\oz+w, \olm+u) \in \gph \partial g$. Since $w\in \ri F_2$, 
as in \eqref{in2}, we can show that $F_1-F_2=F_1 +[w]$.  Employing this and  \eqref{co6} leads us to  
\begin{equation*}
F_1 - F_2 = F_1 +[w] =  \Kg\cap [u]^\perp +[w] = K_g(\oz+w, \olm+u),
\end{equation*}
which completes the proof.
\end{proof}

\begin{Corollary}\label{incri}
For a polyhedral function $g:\R^m\to \oR$  and $(\oz, \olm)\in \gph \partial g$, the following properties hold.
\begin{itemize}[noitemsep,topsep=2pt]
\item [ \rm {(a)}] There exists $r>0$ such that for all $(z, \lm) \in \big(\gph\partial g\big)\cap \B_r(\oz, \olm)$ the following inclusions hold:
\begin{subequations}\label{cri2}
\begin{align}
&\Kgzv \subset \Kg -\Kg,\label{cri2:a}\\
&\Kg \cap -\Kg \subset \Kgzv.\label{cri2:b}
\end{align}
\end{subequations}
\item [ \rm {(b)}] If,  in addition,     $\olm \in \ri\partial g (\oz)$, then there exists $r>0$ such that for all $(z, \lm)\in \big(\gph \partial  g\big)\cap\B_r(\oz, \olm)$, we have $\lm\in \ri \sub g(z)$ and 
\begin{equation}\label{cri1}
\Kgzv = \Kg.
\end{equation}
\end{itemize}
\end{Corollary}

