\la \olm, \zk - \oz\ra &= \sum_{j\in J(\oz)} \osigma_j^k\la a^j, \zk-\oz\ra +\sum_{i\in I(\oz)}\otau_i^k\la b^i, \zk - \oz\ra\nonumber\\
